const incomingRetry = typeof $json.retry_count === 'number' ? $json.retry_count : 0;
const errorMessage = $json.execution?.error?.message || $json.message || 'Unhandled workflow error';
const isRateLimit = /429|Too Many Requests|rate.?limit|Remaining-Req|418/i.test(errorMessage);
return [{
  json: {
    detected_at: new Date().toISOString(),
    project: 'KBIA_UPBIT',
    severity: isRateLimit ? 'critical' : 'high',
    action: isRateLimit ? 'stop_no_retry_rate_limit' : 'stop_log_alert',
    message: errorMessage,
    workflow_name: $json.execution?.workflowData?.name || 'unknown',
    node_name: $json.execution?.lastNodeExecuted || 'unknown',
    retry_count: incomingRetry,
    retry_allowed: false,
    no_order_retry: true,
    telegram_config_present: Boolean($env.KBIA_TELEGRAM_BOT_TOKEN && $env.KBIA_TELEGRAM_CHAT_ID)
  }
}];

return [{
  json: {
    ...$json,
    status: 'alert',
    telegram_text: '<b>KBIA Upbit Alert</b>\n\n' +
      'Execution stopped. Human review required.\n\n' +
      '<b>Workflow:</b> ' + $json.workflow_name + '\n' +
      '<b>Node:</b> ' + $json.node_name + '\n' +
      '<b>Severity:</b> ' + $json.severity + '\n' +
      '<b>Time:</b> ' + $json.detected_at + '\n' +
      '<b>Message:</b> ' + String($json.message).slice(0, 800)
  }
}];

return [{
  json: {
    ...$json,
    status: 'escalate',
    telegram_text: '<b>KBIA Upbit ESCALATION</b>\n\n' +
      'Immediate manual intervention required. No automatic retry is allowed.\n\n' +
      '<b>Workflow:</b> ' + $json.workflow_name + '\n' +
      '<b>Node:</b> ' + $json.node_name + '\n' +
      '<b>Severity:</b> ' + $json.severity + '\n' +
      '<b>Time:</b> ' + $json.detected_at + '\n' +
      '<b>Message:</b> ' + String($json.message).slice(0, 800)
  }
}];
